import numpy as np

class MiniParameter:
    def __init__(self, value):
        self.value = np.asarray(value, dtype=np.float64)

class MiniModule:
    def __init__(self):
        object.__setattr__(self, '_params', {})
    def __setattr__(self, name, value):
        if isinstance(value, MiniParameter):
            self._params[name] = value
        super().__setattr__(name, value)
    def parameters(self):
        return list(self._params.values())
    def __call__(self, x):
        return self.forward(x)
    def forward(self, x):
        raise NotImplementedError

class Linear(MiniModule):
    def __init__(self, in_features, out_features):
        super().__init__()
        # Random init — closer to what nn.Linear actually does.
        self.weight = MiniParameter(np.random.randn(out_features, in_features) * 0.1)
        self.bias = MiniParameter(np.zeros(out_features))
    def forward(self, x):
        return x @ self.weight.value.T + self.bias.value

# Try assembling a two-layer MLP with a ReLU between them.
# Hint: a class that owns two Linear submodules. How many parameters does
# .parameters() give you back? (Note: nested registration of *submodules*
# is not implemented in our MiniModule — you will see only the params
# you assign directly. nn.Module recurses into submodules for you.)

class MLP(MiniModule):
    def __init__(self, in_dim, hidden, out_dim):
        super().__init__()
        self.l1 = Linear(in_dim, hidden)
        self.l2 = Linear(hidden, out_dim)
    def forward(self, x):
        h = self.l1(x)
        h = np.maximum(h, 0)  # ReLU
        return self.l2(h)

model = MLP(in_dim=4, hidden=16, out_dim=2)
x = np.random.randn(3, 4)
print('output shape :', model(x).shape)
print('top-level    :', len(model.parameters()), 'parameters registered (only the ones we assigned directly)')
